    use super::*;

    #[test]
    fn short_month_width_japanese() {
        let max_month_width = 4;
        let month = "1\u{2F49}"; // 1鏈?
        let padding = short_month_padding(max_month_width, month);
        let final_str = format!("{month:<padding$}");
        assert_eq!(max_month_width, UnicodeWidthStr::width(final_str.as_str()));
    }

    #[test]
    fn short_month_width_hindi() {
        let max_month_width = 4;
        assert!([
            "\u{091C}\u{0928}\u{0970}",                         // 啶溹え啷?
            "\u{092B}\u{093C}\u{0930}\u{0970}",                 // 啶ぜ啶班グ
            "\u{092E}\u{093E}\u{0930}\u{094D}\u{091A}",         // 啶ぞ啶班啶?
            "\u{0905}\u{092A}\u{094D}\u{0930}\u{0948}\u{0932}", // 啶呧お啷嵿ぐ啷堗げ
            "\u{092E}\u{0908}",                                 // 啶
            "\u{091C}\u{0942}\u{0928}",                         // 啶溹啶?
            "\u{091C}\u{0941}\u{0932}\u{0970}",                 // 啶溹啶侧グ
            "\u{0905}\u{0917}\u{0970}",                         // 啶呧啷?
            "\u{0938}\u{093F}\u{0924}\u{0970}",                 // 啶膏た啶むグ
            "\u{0905}\u{0915}\u{094D}\u{0924}\u{0942}\u{0970}", // 啶呧啷嵿い啷傕グ
